import{Events as o}from"discord.js";var c={name:o.InteractionCreate,async execute(e){if(!e.isChatInputCommand())return;let a=e.client.commands.get(e.commandName);if(!a){console.error(`No command matching ${e.commandName} was found.`);return}try{await a.execute(e)}catch(r){console.error(r);let m={content:"There was an error while executing this command!",ephemeral:!0};e.replied||e.deferred?await e.followUp(m):await e.reply(m)}}};export{c as default};
